INSERT INTO `v1_b5dac760a46ea19534c7fcb6627f6b13cb3eb7d8345325bfd253bf4c370158e2` VALUES (0, "", "", 6, 21, "vo_minigame_1013", "", "vo_minigame_1013_top_talk_6_001", 0, 6010, "");
